const PRECACHE_HASH = new Map(PRECACHE.map((entry) => [entry.url, entry.hash]))
// Paths served stale-while-revalidate: same names across builds, so refresh behind the cache.
// 2026-10-02 integration fix: `koi-bespoke/` (the bespoke koi atlases) joins `koi/` under
// the same rule; the prefix is matched up to its slash, so `koi` alone never covered it and
// the atlases never reached the runtime cache for offline play.
// 8 October 2026 (OF4): `koi-pilot/` (ume's and the bloom atlas, pilot-atlas.ts) for the same reason.
const STALE_OK = /^\.\/(fonts|estate|bible|koi|art|quotes|assistants|voice|doors|koi-bespoke|koi-pilot)\//
// The sealed tea room's own files, which sit at the root rather than in a
// directory of their own and so match no prefix above: eight encrypted hero
// pictures, the seal's key file and the portrait, 14 MB in all. Without a rule
// a visitor who installed the estate downloaded the whole room and still met a
// lock that could not open without a network. Stale-while-revalidate out of
// RUNTIME, never precached — 14 MB on install is not an install.
const TEA_OK = /^\.\/(ayaka-tea-hero[^/]*\.webp\.enc|tea-seal\.json|ayaka-portrait\.jpg)$/
// Everything the runtime cache holds, and therefore everything the trim measures.
function runtimeOk(rel) {
  return STALE_OK.test(rel) || TEA_OK.test(rel)
}
// Paths never cached: the estate's own live endpoints, which must not go stale.
const LIVE = /^\.\/api\//
// The bundled captures: network first (they may be re-captured between builds),
// but answered from the precache when the network is not there at all.
const SNAPSHOT = /^\.\/snapshot\//
// A navigation waits this long for the network before the precached shell answers.
const NAV_PATIENCE_MS = 3000
// How many revalidated files the cache keeps. The paintings and the 66 tea
// clips are megabytes each; without a ceiling the cache grows for ever.
const STALE_CAP = 240
// And how many *bytes* it keeps. A count alone is not a ceiling: 240 entries of
// paintings and tea clips is hundreds of megabytes on a visitor's device, which
// is not a cache, it is a download. Sizes come from the cached responses'
// own `content-length`; an entry that does not declare one is assumed to be
// this many bytes rather than free, so an unlabelled file cannot hide.
const STALE_BYTE_CAP = 120 * 1024 * 1024
const ASSUMED_BYTES = 256 * 1024
const TRIM_EVERY_MS = 30000
// How many cached entries a trim measures at once. One await per slice instead
// of one per entry; small enough that a deep cache is not read whole.
const TRIM_SLICE = 24
let trimmedAt = 0
// What the device has actually granted. STALE_BYTE_CAP above is the estate's
// own ceiling and it is a fixed number on every device: a phone with a gigabyte
// left and a phone with forty megabytes left were both told to keep 120 MB of
// paintings and tea clips. The browser answers that by evicting the origin's
// storage whole — which costs the visitor the precached shell, the record book
// and the saved games at once, and offline costs them the estate. The cache
// therefore keeps half of what the device says it may have, or the estate's own
// ceiling, whichever is the smaller.
//
// Read once per worker life, off the fetch path: `estimate()` is a round trip
// and a quota does not move while a worker is alive. Where it does not exist —
// Safari before 17, a private window — the constant stands, as it did.
let grantedCap = 0
