        const got = hexOf(await crypto.subtle.digest('SHA-256', bytes))
        controller.signal.throwIfAborted()
        if (held.ok && got === want) return
        phase = 'cache.delete'
        await cache.delete(url)
        controller.signal.throwIfAborted()
